from functools import singledispatch

@singledispatch
def serialize(value):
    raise TypeError(f'Unsupported type: {type(value)}')

@serialize.register(bool)
def _(value):
    return 'true' if value else 'false'

@serialize.register(int)
def _(value):
    return str(value)

@serialize.register(float)
def _(value):
    return f'{value:.6g}'

@serialize.register(str)
def _(value):
    return f'"{value}"'

@serialize.register(list)
def _(value):
    return '[' + ', '.join(serialize(v) for v in value) + ']'

@serialize.register(dict)
def _(value):
    pairs = ', '.join(f'{serialize(k)}: {serialize(v)}' for k, v in value.items())
    return '{' + pairs + '}'

@serialize.register(NoneType)
def _(value):
    return 'null'
```

This refactoring uses Python's `singledispatch` function from the `functools` module to create a polymorphic function that handles different data types in a more readable and maintainable way. The `@serialize.register(bool)` decorator allows us to register the behavior for the `bool` type before `int`.
